  /** True when the circle overlaps the box. */
  hit: boolean;
  /** Penetration depth along the collision normal (0 when not hitting). */
  depth: number;
  /** Unit collision normal, pointing from the box towards the circle center. */
  nx: number;
  ny: number;
}

/**
 * Static circle vs axis-aligned bounding box test.
 *
 * Clamps the circle center to the box to get the closest point on the box,
 * then compares the distance to the radius. When the center lies inside the
 * box, the nearest face determines the exit direction instead.
 */
export function collideCircleAabb(
  cx: number,
  cy: number,
  r: number,
  minX: number,
  minY: number,
  maxX: number,
  maxY: number
): CircleAabbResult {
  // Closest point on the box to the circle center.
  const px = Math.min(Math.max(cx, minX), maxX);
  const py = Math.min(Math.max(cy, minY), maxY);

  let dx = cx - px;
  let dy = cy - py;
  const d2 = dx * dx + dy * dy;

  if (d2 > r * r) {
    return { hit: false, depth: 0, nx: 0, ny: 0 };
  }

  if (d2 > 1e-12) {
    // Center outside the box: push out along the vector to the closest point.
    const d = Math.sqrt(d2);
    const nx = dx / d;
    const ny = dy / d;
    return { hit: true, depth: r - d, nx, ny };
  }

  // Center inside the box: pick the face with the smallest exit distance.
  const left = cx - minX;
  const right = maxX - cx;
  const bottom = cy - minY;
  const top = maxY - cy;

  let depth = left;
  let nx = -1;
  let ny = 0;

  if (right < depth) {
    depth = right;
    nx = 1;
    ny = 0;
  }
  if (bottom < depth) {
    depth = bottom;
    nx = 0;
    ny = -1;
  }
  if (top < depth) {
    depth = top;
    nx = 0;
    ny = 1;
  }

  return { hit: true, depth, nx, ny };
}
