result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/circleAabb.test.ts", "content": "import { describe, expect, it } from "vitest";
import { collideCircleAabb } from "./circleAabb";

const EPS = 1e-9;

describe("collideCircleAabb", () => {
  it("corner case: penetration 2 - sqrt(2) along normalized (1,1)", () => {
    // Box [0,1]^2; circle center (2,2) sits sqrt(2) beyond the corner (1,1).
    const res = collideCircleAabb(2, 2, 2, 0, 0, 1, 1);

    expect(res.hit).toBe(true);
    expect(res.depth).toBeCloseTo(2 - Math.SQRT2, 9);
    expect(res.nx).toBeCloseTo(Math.SQRT1_2, 9); // 1/sqrt(2)
    expect(res.ny).toBeCloseTo(Math.SQRT1_2, 9);

    // Explicit diagonal check: |n| == 1 and n.x === n.y.
    expect(Math.hypot(res.nx, res.ny)).toBeCloseTo(1, EPS);
    expect(res.nx).toBeCloseTo(res.ny, EPS);
  });

  it("center inside the box picks nearest face normal", () => {
    // Box [0,10]^2, center (8,5): right face is only 2 away.
    const res = collideCircleAabb(8, 5, 3, 0, 0, 10, 10);

    expect(res.hit).toBe(true);
    expect(res.depth).toBeCloseTo(2, EPS);
    expect(res.nx).toBeCloseTo(1, EPS);
    expect(res.ny).toBeCloseTo(0, EPS);

    // Same box, center near the bottom face instead.
    const res2 = collideCircleAabb(5, 1, 4, 0, 0, 10, 10);
    expect(res2.depth).toBeCloseTo(1, EPS);
    expect(res2.nx).toBeCloseTo(0, EPS);
    expect(res2.ny).toBeCloseTo(-1, EPS);
  });

  it("exactly touching a face reports zero penetration, not a collision", () => {
    // Box [0,4]^2, circle of radius 2 centered at x = 6 touches x = 4 exactly.
    const res = collideCircleAabb(6, 2, 2, 0, 0, 4, 4);

    expect(res.hit).toBe(false);
    expect(res.depth).toBeCloseTo(0, EPS);
    expect(res.nx).toBe(0);
    expect(res.ny).toBe(0);
  });
});
"})
